"""Verify both regenerated byte identities and the named generated definitions."""
import argparse
import gzip
import hashlib
import json
from pathlib import Path
import re
import subprocess

p = argparse.ArgumentParser()
p.add_argument('source', type=Path)
p.add_argument('output', type=Path)
p.add_argument('evidence', type=Path)
args = p.parse_args()
ledger = json.loads((args.source/'release/generated-license-evidence.json').read_bytes())
identity = json.loads(subprocess.check_output(['python3', 'scripts/git_identity.py', 'inspect', 'HEAD'], cwd=args.source))
assert identity['source_commit'] == '5a7ec57bba4c4021c0bc1d3f34f00eed892bf19c'
table = (args.output/'functions.txt').read_bytes()
table_hash = hashlib.sha256(table).hexdigest()
guest_hash = hashlib.sha256((args.output/'guest.wasm').read_bytes()).hexdigest()
assert table_hash == ledger['symbol_map_sha256'] and guest_hash == ledger['guest_sha256']
pairs = [line.split(':', 1) for line in table.decode().splitlines()]
names = {int(i): name for i, name in pairs}
assert len(names) == len(pairs) == ledger['symbol_map_entries'] == 21791
found = {}
for target in ('emb_stmt_execute', 'process_triggers', 'dlmalloc'):
    index, = [i for i,n in names.items() if (n == target if target == 'dlmalloc' else target in n)]
    definition = re.compile(r'^func Fn'+str(index)+r'\(m \*base\.Module\b.*\{',re.M)
    matches = []
    for path in sorted((args.source/'internal/generatedgo/code').glob('p*/*.go')):
        body = path.read_text()
        for match in definition.finditer(body):
            matches.append(dict(file=str(path.relative_to(args.source)), line=body.count('\n',0,match.start())+1, signature=match[0]))
    entry, = matches
    found[target] = dict(index=index, named_symbol=names[index], **entry)
record = dict(source_commit=identity['source_commit'], audited_commit=ledger['audit_source_commit'],
              guest_sha256=guest_hash, symbol_map_sha256=table_hash, entries=len(names), definitions=found)
(args.evidence/'phase1.json').write_text(json.dumps(record,indent=2)+'\n')
(args.evidence/'functions.txt.gz').write_bytes(gzip.compress(table,mtime=0))
print(json.dumps(record,indent=2))
